    expect(call.json).toEqual({
      performUpsert: { fieldsToMergeOn: ['Order Number'] },
      records: [
        {
          fields: {
            'Order Number': '9876543210',
            'Customer Email': 'buyer@example.com',
            Total: 299.5,
            'HMAC Digest': 'deadbeefcafe',
          },
        },
      ],
    });
    expect(result).toEqual({ createdRecordIds: ['recNew123'], updatedRecordIds: [] });
  });

  it('includes bearer token authentication header', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      records: [{ id: 'rec1' }],
      updatedRecords: ['rec1'],
      createdRecords: [],
    }, 200));
    const config = { ...baseConfig, airtableApiKey: 'secret-key-123', fetch };
    const payload: ShopifyOrderPaidPayload = {
      id: '111',
      customer: { email: 'a@b.com' },
      total_price: '10.00',
      hmac: 'hmac1',
    };
    await handle(payload, config);
    expect(calls[0].headers.get('authorization')).toBe('Bearer secret-key-123');
  });

  it('throws descriptive error when id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = { customer: { email: 'x@y.com' }, total_price: '1', hmac: 'h' } as unknown as ShopifyOrderPaidPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: id');
  });

  it('throws descriptive error when customer.email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = { id: '1', customer: {}, total_price: '1', hmac: 'h' } as unknown as ShopifyOrderPaidPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: customer.email');
  });

  it('throws descriptive error when total_price is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = { id: '1', customer: { email: 'x@y.com' }, hmac: 'h' } as unknown as ShopifyOrderPaidPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: total_price');
  });

  it('throws descriptive error when hmac is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = { id: '1', customer: { email: 'x@y.com' }, total_price: '1' } as unknown as ShopifyOrderPaidPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: hmac');
  });

  it('throws error with status code and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config = { ...baseConfig, fetch };
    const payload: ShopifyOrderPaidPayload = {
      id: '1',
      customer: { email: 'x@y.com' },
      total_price: '1',
      hmac: 'h',
    };
    await expect(handle(payload, config)).rejects.toThrow('Airtable upsert failed: 401 Unauthorized at https://api.airtable.com/v0/appTestBase/tblTestTable');
    expect(calls).toHaveLength(1);
  });

  it('returns both created and updated record IDs from response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      records: [
        { id: 'recCreated' },
        { id: 'recUpdated' },
      ],
      updatedRecords: ['recUpdated'],
      createdRecords: ['recCreated'],
    }, 200));
    const config = { ...baseConfig, fetch };
    const payload: ShopifyOrderPaidPayload = {
      id: '1',
      customer: { email: 'x@y.com' },
      total_price: '1',
      hmac: 'h',
    };
    const result = await handle(payload, config);
    expect(result).toEqual({ createdRecordIds: ['recCreated'], updatedRecordIds: ['recUpdated'] });
  });
});

